package com.etpms.dao;
import com.etpms.model.User;import com.etpms.util.DB;import java.sql.*;
public class UserDAO {
 public User authenticate(String username,String password)throws SQLException{String q="SELECT u.id,u.username,u.role,u.password_hash,u.password_salt,e.first_name,e.last_name,e.email FROM users u LEFT JOIN employees e ON e.user_id=u.id WHERE u.username=? AND u.active=1";try(Connection c=DB.get();PreparedStatement p=c.prepareStatement(q)){p.setString(1,username);try(ResultSet r=p.executeQuery()){if(!r.next()||!com.etpms.util.Passwords.verify(password,r.getString("password_salt"),r.getString("password_hash")))return null;User u=new User();u.id=r.getLong("id");u.username=r.getString("username");u.role=r.getString("role");u.firstName=r.getString("first_name");u.lastName=r.getString("last_name");u.email=r.getString("email");return u;}}}
 public static void ensureDemoUsers()throws SQLException{try(Connection c=DB.get();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM users")){r.next();if(r.getInt(1)>0)return;}try(Connection c=DB.get()){c.setAutoCommit(false);try(PreparedStatement u=c.prepareStatement("INSERT INTO users(username,password_hash,password_salt,role) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS);PreparedStatement d=c.prepareStatement("INSERT IGNORE INTO departments(name,description) VALUES(?,?)");PreparedStatement e=c.prepareStatement("INSERT INTO employees(user_id,department_id,first_name,last_name,email,job_title,manager_id) VALUES(?,?,?,?,?,?,?)")){d.setString(1,"Operations");d.setString(2,"Operations and delivery");d.executeUpdate();long dep;try(Statement st=c.createStatement();ResultSet rs=st.executeQuery("SELECT id FROM departments WHERE name='Operations'")){rs.next();dep=rs.getLong(1);}String[][] people={{"admin","ADMIN","Admin","User","admin@company.local","Administrator"},{"manager","MANAGER","Morgan","Manager","manager@company.local","Team Manager"},{"employee","EMPLOYEE","Evan","Employee","employee@company.local","Associate"}};long managerId=0;for(String[] person:people){String salt=com.etpms.util.Passwords.salt();u.setString(1,person[0]);u.setString(2,com.etpms.util.Passwords.hash("pass@123",salt));u.setString(3,salt);u.setString(4,person[1]);u.executeUpdate();long id;try(ResultSet keys=u.getGeneratedKeys()){keys.next();id=keys.getLong(1);}if(!"ADMIN".equals(person[1])){e.setLong(1,id);e.setLong(2,dep);e.setString(3,person[2]);e.setString(4,person[3]);e.setString(5,person[4]);e.setString(6,person[5]);if("EMPLOYEE".equals(person[1]))e.setLong(7,managerId);else e.setNull(7,Types.BIGINT);e.executeUpdate();if("MANAGER".equals(person[1]))try(Statement st=c.createStatement();ResultSet rs=st.executeQuery("SELECT id FROM employees WHERE user_id="+id)){rs.next();managerId=rs.getLong(1);}}}c.commit();}catch(SQLException|RuntimeException ex){c.rollback();throw ex;}}}
}
